package dsa

import (
	"testing"
	"go.uber.org/goleak"
)

func TestCompactUnique_Correctness(t *testing.T) {
	defer goleak.VerifyNone(t)
	nums := []int{1, 1, 2, 2, 3, 3, 4}
	got := CompactUnique(nums)
	if len(got) != 4 { t.Fatalf("expected 4 unique, got %d", len(got)) }
}

func BenchmarkCompactUnique_Staff(b *testing.B) {
	nums := make([]int, 10000)
	for i := range nums { nums[i] = i % 100 }
	b.ReportAllocs()
	b.ResetTimer()
	for i := 0; i < b.N; i++ {
		_ = CompactUnique(nums)
	}
}

func TestCompactUnique_AllocBudget(t *testing.T) {
	nums := make([]int, 10000)
	for i := range nums { nums[i] = i % 100 }
	allocs := testing.AllocsPerRun(100, func() {
		_ = CompactUnique(nums)
	})
	if allocs > 0 {
		t.Errorf("Staff violation: expected <= 0 allocs/run, got %.2f", allocs)
	}
}

